<?php declare(strict_types=1); ?><div class="mb-5 flex justify-end"><a class="btn btn-primary" href="<?= e(admin_url('blog/new')) ?>">New article</a></div><div class="card divide-y divide-hairline"><?php if(!$rows): ?><p class="p-8 text-center text-muted">No articles yet.</p><?php endif; ?><?php foreach($rows as $row): ?><a class="flex items-center gap-4 px-5 py-4 hover:bg-canvas" href="<?= e(admin_url('blog/'.$row['id'])) ?>"><?php if($row['cover']): ?><img class="h-12 w-16 rounded object-cover" src="<?= e(asset($row['cover'])) ?>" alt=""><?php endif; ?><div class="flex-1"><p class="font-semibold text-navy-700"><?= e($row['title']) ?></p><p class="t-meta text-muted"><?= e($row['category']?:'Uncategorised') ?> · /blog/<?= e($row['slug']) ?></p></div><?php if($row['featured']): ?><span class="badge bg-gold-100 text-gold-600">Featured</span><?php endif; ?><span class="badge <?= $row['published_at']?'bg-verified/10 text-verified':'bg-navy-100 text-navy-700' ?>"><?= $row['published_at']?'Published':'Draft' ?></span></a><?php endforeach; ?></div>
